  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  if (delimiter.length !== 1) throw new CsvError('delimiter must be a single character');
  if (quote.length !== 1) throw new CsvError('quote must be a single character');
  if (delimiter === quote) throw new CsvError('delimiter and quote must differ');
  if (isLineTerminatorChar(delimiter) || isLineTerminatorChar(quote)) {
    throw new CsvError('delimiter and quote must not be line terminators');
  }
  return { delimiter, quote };
}

